private static String subst(String value, Properties props) {
    int startIndex = value.indexOf("${");
    while (startIndex != -1) {
        int endIndex = value.indexOf("}", startIndex);
        if (endIndex == -1) {
            break;
        }
        String varName = value.substring(startIndex + 2, endIndex);
        String varValue = props.getProperty(varName);
        if (varValue != null) {
            value = value.substring(0, startIndex) + varValue + value.substring(endIndex + 1);
        }
        startIndex = value.indexOf("${", startIndex);
    }
    return value;
}
